    name: 'rtlPlacement',
    fn({ elements, placement }: MiddlewareArguments): MiddlewareReturn {
        const rtl = getComputedStyle(elements.floating).direction === 'rtl';
        return { data: { placement: getInvertedRTLPlacement(placement, rtl) } };
    },
});

